class TreeNode {

    int val;
    TreeNode left;
    TreeNode right;

    TreeNode() {
    }

    TreeNode(int val) {
        this.val = val;
    }

    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

import org.junit.jupiter.api.Disabled;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;

@DisplayName("80/75_flatten_binary_tree_to_linked_list (incomplete)")
class SolutionIncompleteTest {

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldFlattenExampleTree() {

        Solution solution = new Solution();

        TreeNode root = new TreeNode(
            1,
            new TreeNode(2, new TreeNode(3), new TreeNode(4)),
            new TreeNode(5, null, new TreeNode(6))
        );

        solution.flatten(root);

        assertEquals(Arrays.asList(1, 2, 3, 4, 5, 6), collectRightSpine(root));
        assertAllLeftNull(root);
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldHandleEmptyTree() {

        Solution solution = new Solution();

        solution.flatten(null);
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldHandleSingleNode() {

        Solution solution = new Solution();

        TreeNode root = new TreeNode(0);

        solution.flatten(root);

        assertEquals(Arrays.asList(0), collectRightSpine(root));
        assertNull(root.left);
        assertNull(root.right);
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldFlattenLeftSkewedTree() {

        Solution solution = new Solution();

        TreeNode root = new TreeNode(1, new TreeNode(2, new TreeNode(3), null), null);

        solution.flatten(root);

        assertEquals(Arrays.asList(1, 2, 3), collectRightSpine(root));
        assertAllLeftNull(root);
    }

    private List<Integer> collectRightSpine(TreeNode root) {

        List<Integer> values = new ArrayList<>();
        TreeNode current = root;

        while (current != null) {
            values.add(current.val);
            current = current.right;
        }

        return values;
    }

    private void assertAllLeftNull(TreeNode root) {

        TreeNode current = root;

        while (current != null) {
            assertNull(current.left);
            current = current.right;
        }
    }
}

